export async function kitGraphqlExecuteRead(handle: KitGraphqlHandle, batch: ReadCommandBatch): Promise<ReadCommandBatchResult> {
  const q = `query ($batch: JSON!) { kitStore { readKitCommands(batch: $batch) } }`;
