  getPiecesMetadata(designId: string) {
    if (!kitWorkerHandle) throw new Error("KitStoreHandle not initialized");
    return settle(Promise.resolve(kitWorkerHandle.getPiecesMetadata(designId)));
  },
  getPieces(designId: string) {
    if (!kitWorkerHandle) throw new Error("KitStoreHandle not initialized");
