  },
  getDesigns() {
    if (!kitWorkerHandle) throw new Error("KitStoreHandle not initialized");
    return settle(Promise.resolve(kitWorkerHandle.getDesigns()));
  },
  getTypes() {
    if (!kitWorkerHandle) throw new Error("KitStoreHandle not initialized");
